local _, WFJ = ...
WFJ.Data.add("spell", {
  [473384] = { "Usa il manuale per chiamare il tuo Argent Squire a una lezione di combattimento contro i silitidi. I silitidi uccisi in presenza dello scudiero aumenteranno la tua reputazione con l'⟦Argent Dawn=Alba d'Argento⟧.", "Il tuo scudiero ti accompagna. Ottieni reputazione con l'⟦Argent Dawn=Alba d'Argento⟧ uccidendo silitidi.", 0xec5a51f0, 0x70ae3586, "uu" },
  [473387] = { "Raduna i membri del gruppo o dell'incursione vicini, conferendo loro un aumento del $N1% della probabilità di critico magico, del $N2% della probabilità di critico in mischia e a distanza e di $N3 della potenza d'attacco. Dura $D1. Non si somma ad altri effetti globali simili e non è influenzato dai Chronoboon.", "Aumenta la probabilità di critico degli incantesimi del $N1%, in mischia e a distanza del $N2% e conferisce $N3 potenza d'attacco.", 0x87cc436e, 0x04d1ed33, "uu" },
  [473399] = { "Evoca un fiorcanto che conferisce a tutti i membri del tuo gruppo o della tua incursione un aumento del $N1% della probabilità di critico in mischia, a distanza o magico e di $N2 a tutte le caratteristiche per $D1. Non si somma ad altri effetti globali simili. Non è influenzato dai Chronoboon.", "Aumenta la probabilità di critico in mischia, a distanza o magico del $N1% e tutte le caratteristiche di $N2.", 0x6a7a8d25, 0x1e139466, "uu" },
  [473403] = { "Conferisce a tutti i membri del gruppo o dell'incursione vicini un aumento di $N1 della potenza d'attacco, del $N2% della Tempra e del $N3% della probabilità di critico magico per $D1. Non si somma ad altri effetti globali simili. Non è influenzato dai Chronoboon.", "Aumenta la potenza d'attacco di $N1, la Tempra del $N2% e la probabilità di critico magico del $N3%.", 0xb78582ac, 0x23a55955, "uu" },
  [473441] = { "Aumenta la salute di $N1. Velocità degli attacchi in mischia aumentata del $N2%. Rigenera $N3 mana ogni $N4 s.", "Aumenta la salute di $N1. Velocità degli attacchi in mischia aumentata del $N2%. Rigenera $N3 mana ogni $N4 s.", 0xc53fc1df, 0xc53fc1df, "uu" },
  [473450] = { "Conferisce a tutti i membri del tuo gruppo o della tua incursione un aumento del $N1% dei danni inflitti per $D1.", "Aumenta i danni del $N1%.", 0x74575d7f, 0x416dea0f, "uu" },
  [473466] = { "Evoca per $D1 un calderone di acquavite, utilizzabile da tutti i membri del tuo gruppo o della tua incursione per aumentare la potenza d'attacco in mischia di $N2 e le dimensioni per $D2.", nil, 0x0fcd9860, nil, "um" },
  [473469] = { "Aumenta la tua potenza d'attacco in mischia di $N1 e le tue dimensioni per $D1.", "Dimensioni e potenza d'attacco in mischia aumentate di $N1.", 0x1f3c4cc7, 0x1bbffd49, "uu" },
  [473476] = { "Conferisce a tutti i membri del tuo gruppo o della tua incursione un aumento del $N1% della velocità di movimento e del $N2% delle caratteristiche per $D1.", "Aumenta la velocità di movimento del $N1% e tutte le caratteristiche del $N2%.", 0x2d11f2b5, 0x0d29e698, "uu" },
  [473482] = { "Indebolisce i membri elementali dell'Abyssal Council a ⟦Silithus=Silitus⟧, riducendo del $N1% tutti i danni che infliggono. Dura $D1.", "Danni inflitti ridotti del $N1%.", 0x093a0b91, 0x618d76ee, "uu" },
  [473493] = { "Piazza in un punto vicino una trappola che esplode quando si avvicina un silitide dell'⟦Hive'Ashi=Alveare Ashi⟧, dell'⟦Hive'Regal=Alveare Regal⟧ o dell'⟦Hive'Zora=Alveare Zora⟧, facendogli subire danni pari al $N1% della sua salute ogni $D1 per $D2.", nil, 0xc93b98f4, nil, "um" },
  [473496] = { nil, "Subisci danni da fuoco pari al $N1% della salute ogni $N2 s.", nil, 0xcf9f5348, "mu" },
  [473525] = { "Congela per $D1 un silitide nell'⟦Hive'Ashi=Alveare Ashi⟧, nell'⟦Hive'Regal=Alveare Regal⟧ o nell'⟦Hive'Zora=Alveare Zora⟧. Qualsiasi danno interrompe l'effetto.", nil, 0x3bfe5a1c, nil, "um" },
  [473544] = { "Inalare questo incenso ti fa svanire nelle ombre e ti permette di muoverti furtivamente nell'⟦Hive'Ashi=Alveare Ashi⟧, nell'⟦Hive'Regal=Alveare Regal⟧ o nell'⟦Hive'Zora=Alveare Zora⟧, ma riduce la tua velocità del $N1%. Dura $D1.", "Furtivo. Movimento rallentato del $N1%.", 0x2b7ea238, 0xbaa2cba7, "uu" },
  [473561] = { "Lancia l'antica corda per immobilizzare un silitide dell'⟦Hive'Ashi=Alveare Ashi⟧, dell'⟦Hive'Regal=Alveare Regal⟧ o dell'⟦Hive'Zora=Alveare Zora⟧ e tirarlo verso di te. Non utilizzabile su nemici di livello superiore a $N1 o contrassegnati come boss.", nil, 0xcf940655, nil, "um" },
  [473570] = { nil, "Immune agli effetti di stordimento.", nil, 0xfd2ef3a2, "mu" },
  [473687] = { nil, "Finché uno scudiero argenteo è presente nel tuo gruppo o nella tua incursione, uccidere silitidi nell'⟦Hive'Ashi=Alveare Ashi⟧, nell'⟦Hive'Regal=Alveare Regal⟧ e nell'⟦Hive'Zora=Alveare Zora⟧ conferisce reputazione con l'⟦Argent Dawn=Alba d'Argento⟧.", nil, 0x3775c508, "mu" },
  [473701] = { "Costringe il bersaglio ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", "Provocato.", 0x71de38fd, 0x36f56123, "uu" },
  [473702] = { "Usa il ramo per chiamare un ⟦Ancient of War=Antico della Guerra⟧ che ti aiuti a combattere i silitidi.", nil, 0x65c2a94b, nil, "um" },
  [473847] = { "Evoca e congeda un carro da battaglia qiraji cavalcabile. È una cavalcatura molto veloce.", nil, 0x46e67ef3, nil, "um" },
